    /**
     * Tests creating a new ExchangeRate.
     *
     * @return    ExchangeRate
     */
    public ExchangeRate testCreate() throws Throwable {
    ExchangeRate entity = null;

    LOGGER.info( "ExchangeRateTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a ExchangeRate");

    StringBuilder msg = new StringBuilder( "-- Failed to create a ExchangeRate" );

    try {
        entity = service.createExchangeRate( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getExchangeRateId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a ExchangeRate with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

