    /**
     * Tests getting all ExchangeRates.
     *
     * @return    Collection
     */
    public List<ExchangeRate> testGetAll() throws Throwable {
    LOGGER.info( "ExchangeRateTest:testGetAll() - Retrieving Collection of ExchangeRates:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ExchangeRate : " );
    List<ExchangeRate> collection  = null;

    try {
        // call the static get method on the ExchangeRateService
        collection = service.getAllExchangeRate();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ExchangeRate currEntity  = null;
            Iterator<ExchangeRate> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getExchangeRateId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

